{"content":"from heapq import nsmallest, nlargest

def percentile(xs, p):
    """The p-th percentile (0 <= p <= 100) of a list of numbers, by linear
    blending: sort the list, find position r = p / 100 * (n - 1), and blend
    the items at floor(r) and floor(r) + 1 by the fraction part of r.
    Floats may differ from this function only by rounding (relative 1e-6).
    Raises ValueError on an empty list or p outside 0 to 100."""
    if not xs or p < 0 or p > 100:
        raise ValueError("bad input")
    n = len(xs)
    if n == 1:
        return float(xs[0])
    r = p / 100 * (n - 1)
    lo = int(r)
    frac = r - lo
    if frac == 0.0:
        if lo == 0:
            return float(min(xs))
        if lo == n - 1:
            return float(max(xs))
        kb = lo + 1
        kt = n - lo
        if kb < kt:
            return float(nsmallest(kb, xs)[-1])
        return float(nlargest(kt, xs)[-1])
    kb = lo + 2
    kt = n - lo
    if kb < kt:
        s = nsmallest(kb, xs)
        a = s[lo]
        b = s[lo + 1]
    else:
        s = nlargest(kt, xs)
        a = s[-1]
        b = s[-2]
    return a + (b - a) * frac
"}

{"content":"def percentile(xs, p):
    if not xs or p < 0 or p > 100:
        raise ValueError("bad input")
    n = len(xs)
    if n == 1:
        return float(xs[0])
    s = sorted(xs)
    r = p / 100 * (n - 1)
    lo = int(r)
    frac = r - lo
    if lo + 1 < n:
        return s[lo] + (s[lo + 1] - s[lo]) * frac
    return float(s[lo])
